def _acf_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(
        f"invalid aggregate chain fork proof: {message}"
    )


def _acf_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid aggregate chain fork decision: {message}"
    )


def _reject_duplicate_acf_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _acf_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_acf_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate aggregate chain fork proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidChainProofError`.  The two policy bindings, the
    moment and the signature are checked by the proof verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _acf_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _acf_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_acf_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _acf_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _CF_PROOF_TOP_KEYS:
        raise _acf_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _acf_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _ACF_PROOF_PAYLOAD_KEYS:
        raise _acf_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'prunePolicy', 'report', "
            "'authorizationPolicy' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _acf_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _acf_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _acf_proof_invalid("payload moment must be non-negative")
    for field in (CF_PROOF_PRUNE_POLICY, _ACF_PROOF_AUTHORIZATION_POLICY):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _acf_proof_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != AGGREGATE_CHAIN_FORK_PROOF_VERSION:
        raise _acf_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(
        payload[FORK_PROOF_CHAINS], invalid=_acf_proof_invalid
    )
    _validated_pac_fork_report(
        payload[FORK_PROOF_REPORT], chains,
        conflicted_error=_CDA_CHAIN_ITEM_ERROR,
        invalid=_acf_proof_invalid,
        report_version=DECISION_AGGREGATE_CHAINS_VERSION,
    )

    if _prune_compact(data) != raw:
        raise _acf_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_aggregate_chain_fork_proof(items, prune_policy,
                                    authorization_policy, keyring, moment,
                                    issuer, version):
    """Sign the fork summary of a decision aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_decision_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original ``{"batch","sites","threshold"}``
    pruning policy and ``authorization_policy`` the shared invariant site
    authorization policy, ``keyring`` follows the existing rules,
    ``moment`` is the signing time and ``issuer``/``version`` name the
    signing credentials.  The batch first runs through the exact
    :func:`verify_decision_aggregate_chains` rules and the proof is
    issued only when the resulting report records at least one fork (a
    fork-free report raises :class:`ValueError`).  No file is read or
    written and no argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every object
    key recursively sorted, non-ASCII preserved, no trailing newline or
    any other trailing byte -- carrying exactly ``payload`` and
    ``signature``.  The payload binds exactly ``chains`` (every input
    chain in input order: ``id``, the ``root`` digest, every
    ``successors`` digest and the canonical digest of every versioned
    decision site policy in the complete ``policies`` history),
    ``issuer``, ``keyVersion``, ``moment``, ``prunePolicy`` (the
    lowercase hex SHA-256 of the canonical compact prune policy
    encoding), ``report`` (the complete chain-batch report),
    ``authorizationPolicy`` (the SHA-256 of the canonical compact site
    authorization policy) and ``version`` (the integer 1).  ``signature``
    is the lowercase hex HMAC-SHA256 of the canonical compact payload
    bytes under the key the keyring binds to the exact issuer and
    version, with no fallback.

    A parameter or public field type fault raises :class:`TypeError` (a
    :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy or a report
    without a fork raises :class:`ValueError`; and unknown, revoked,
    not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_fac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_decision_aggregate_chains(
        validated_items, prune_policy, authorization_policy, keyring,
        sign_moment,
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "an aggregate chain fork proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        CF_PROOF_PRUNE_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        _ACF_PROOF_AUTHORIZATION_POLICY: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_authorization_policy)
        ).hexdigest(),
        VERSION: AGGREGATE_CHAIN_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_acf_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one aggregate chain fork proof against validated materials.

    Shared core of the batch verifier; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_acf_fork_proof(raw)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[CF_PROOF_PRUNE_POLICY] != expected_prune_digest:
        raise _acf_proof_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACF_PROOF_AUTHORIZATION_POLICY] != expected_authorization_digest:
        raise _acf_proof_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _acf_proof_invalid(
            "moment must not be later than the verification moment"
        )

    key_entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate chain fork proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        _ACF_AUTHORIZATION_POLICY_DIGEST: expected_authorization_digest,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: AGGREGATE_CHAIN_FORK_PROOF_VERSION,
    }


# -- Offline batch verification of aggregate chain fork proofs ----------------

def _acf_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One aggregate chain fork proof batch report, fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_acf_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one aggregate chain fork proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_acf_fork_proof_core(
            item[FORK_PROOF_ITEM_PROOF],
            validated_prune_policy,
            validated_authorization_policy,
            validated_keyring,
            moment,
        )
    except AuthenticationError as exc:
        return _acf_proofs_item_report(
            item_id, _ACF_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidChainProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _acf_proofs_item_report(
            item_id, _ACF_PROOFS_INVALID, str(exc), None
        )
    return _acf_proofs_item_report(
        item_id, _ACF_PROOFS_VERIFIED, None, result
    )


def verify_aggregate_chain_fork_proofs(items, prune_policy,
                                      authorization_policy, keyring, moment):
    """Verify a whole batch of aggregate chain fork proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
    keys ``id`` (a non-empty str, unique across the batch) and ``proof``
    (the bytes :func:`sign_aggregate_chain_fork_proof` produced).  The

        authorization_policy
    )
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()

    rows = [
        _adjudicate_acf_one(
            item, prune_policy_digest, authorization_policy_digest,
            validated_signer_site_policy, validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _CF_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_signer_site_policy[ADJ_THRESHOLD]:
            status = _CF_STATUS_ACCEPTED
        else:
            status = _CF_STATUS_INSUFFICIENT
    else:
        status = _CF_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )
    # The proof summary vector corresponds term by term to the canonical
    # (sorted) rows, so a reordering of the summaries that is then
    # re-signed is detectable offline without seeing any proof even
    # though the digest multiset is unchanged.
    proof_digests = [row[_CF_PROOF_DIGEST] for row in rows]

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        _CF_DECISION_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _CF_DECISION_PROOFS: proof_digests,
        _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST: authorization_policy_digest,
        PAFD_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_signer_site_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: AGGREGATE_CHAIN_FORK_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_acf_decision(raw: object) -> tuple[dict, str]:
    """Validate aggregate chain fork decision bytes structurally.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidChainDecisionError`.  The policy, tally and
    credential bindings are checked by the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _acf_decision_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _acf_decision_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=lambda pairs: _reject_duplicate_pafd_keys(
                pairs, _acf_decision_invalid
            ),
        )
    except json.JSONDecodeError as exc:
        raise _acf_decision_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _acf_decision_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _acf_decision_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _ACF_DECISION_PAYLOAD_KEYS:
        raise _acf_decision_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'authorizationPolicyDigest', 'sitePolicyDigest', 'status' "
            "and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _acf_decision_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _acf_decision_invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise _acf_decision_invalid("payload status is not a known status")
    for field in (
        PAFD_PRUNE_POLICY_DIGEST,
        _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST,
        PAFD_SITE_POLICY_DIGEST,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _acf_decision_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise _acf_decision_invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _acf_decision_invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise _acf_decision_invalid("payload items must be non-empty")
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise _acf_decision_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'digest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _acf_decision_invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise _acf_decision_invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[_CF_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _acf_decision_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise _acf_decision_invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _acf_decision_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _acf_decision_invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise _acf_decision_invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise _acf_decision_invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise _acf_decision_invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise _acf_decision_invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise _acf_decision_invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            if not raw_edges:
                raise _acf_decision_invalid(
                    f"{where} edges must be non-empty for an authenticated "
                    "proof"
                )
            row_edges = [
                _validated_pafd_edge(value, where, _acf_decision_invalid)
                for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise _acf_decision_invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise _acf_decision_invalid(
                    f"{where} edges must be sorted ascending"
                )
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise _acf_decision_invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise _acf_decision_invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        if not common:
            raise _acf_decision_invalid(
                "a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(value, "payload common",
                                 _acf_decision_invalid)
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _acf_decision_invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != AGGREGATE_CHAIN_FORK_DECISION_VERSION:
        raise _acf_decision_invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise _acf_decision_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def verify_aggregate_chain_fork_decision(decision, prune_policy,
                                        authorization_policy,
                                        signer_site_policy, keyring, moment):
    """Re-verify a signed aggregate chain fork decision entirely offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    invariant site ``authorization_policy``, the expected
    ``signer_site_policy``, the current ``keyring`` and the
    verification ``moment`` are consulted -- no file is read or written
    and no argument is modified.  The decision binds three policy
    digests (the prune policy, the site authorization policy and the
    signer site policy).  Verification validates the canonical encoding
    and every key set, recomputes all three policy digests, re-tallies
    the bound per-proof rows purely from the signed payload (the
    term-by-term proof digest bindings over the canonical rows, the
    stable site/id row ordering, the same-site
    duplicate/contradiction markings, the cross-site complete
    edge-set agreement, the signer threshold outcome and the claimed
    common set), and checks the HMAC-SHA256 against the key the current
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the decision with no fallback.

    On success a fresh depth-independent mapping is returned with the
    fixed keys ``common``, ``proofDigest`` (the SHA-256 of the decision
    bytes), ``issuer``, ``items``, ``keyVersion``,
    ``prunePolicyDigest``, ``proofs``, ``authorizationPolicyDigest``,
    ``sitePolicyDigest``, ``status`` and ``version`` (the integer 1);
    repeated calls return equal but mutually independent objects and
    unauthenticated identities and boundaries never enter a result.  A
    non-bytes decision or a wrong public field type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, a duplicate id, a wrong key set or an illegal policy,
    threshold, moment, identity or version raises :class:`ValueError`;
    an illegal decision structure, ordering, tally or binding raises
    :class:`InvalidChainDecisionError` (a :class:`ValueError` subclass,
    distinct from :class:`InvalidChainProofError`); unknown, revoked,
    not-yet-valid or expired credentials or a wrong signature raise
    :class:`AuthenticationError`.
    """
    if not isinstance(decision, bytes):
        raise TypeError("decision must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return _verify_acf_decision_core(
        decision, validated_prune_policy, validated_authorization_policy,
        validated_signer_site_policy, validated_keyring, verify_moment,
    )


def _verify_acf_decision_core(
    decision: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_signer_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one aggregate chain fork decision against validated materials.

    This is the shared core of
    :func:`verify_aggregate_chain_fork_decision` and the batch
    :func:`verify_aggregate_chain_fork_decisions`; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated decision material.
    """
    payload, signature = _parse_acf_decision(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _acf_decision_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACF_DECISION_AUTHORIZATION_POLICY_DIGEST] != \
            expected_authorization_digest:
        raise _acf_decision_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    expected_signer_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest()
    if payload[PAFD_SITE_POLICY_DIGEST] != expected_signer_digest:
        raise _acf_decision_invalid(
            "site policy digest does not match the signer site policy"
        )

    # The proof digest vector is bound term by term to the canonical
    # (stably sorted) rows, so a reordering of the summaries that is then
    # re-signed is rejected even though the digest multiset is unchanged.
    status = _reconcile_pafd(
        payload, validated_signer_site_policy[ADJ_THRESHOLD],
        invalid=_acf_decision_invalid, positional_proofs=True,
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate chain fork decision signature does not match"
        )

    return {
        key: copy.deepcopy(value)
        for key, value in (
            (PAFD_COMMON, payload[PAFD_COMMON]),
            (FORK_PROOF_DIGEST, hashlib.sha256(decision).hexdigest()),
            (VD_ISSUER, payload[VD_ISSUER]),
            (ITEMS, payload[ITEMS]),
            (KEY_VERSION, payload[KEY_VERSION]),
            (PAFD_PRUNE_POLICY_DIGEST, expected_prune_digest),
            (PAFD_PROOFS, payload[PAFD_PROOFS]),
            (_ACF_DECISION_AUTHORIZATION_POLICY_DIGEST,
             expected_authorization_digest),
            (PAFD_SITE_POLICY_DIGEST, expected_signer_digest),
            (STATUS, status),
            (VERSION, AGGREGATE_CHAIN_FORK_DECISION_VERSION),
        )
    }


# ===========================================================================
# Batch verification and cross-site aggregation of aggregate chain fork
# decisions
# ===========================================================================
#
# This layer mirrors the chain fork decision aggregate (``cfda``) layer
# but its source packets are :func:`adjudicate_aggregate_chain_forks`
# decisions: the per-proof summaries are bound term by term to the
# canonical site/id-sorted rows, the packet carries four policy digests
# (the prune policy, the site authorization policy, the signer site
# policy and the decision site policy), and the error hierarchy is its
# own.  The wire field names otherwise follow the ``cfda`` layer.

AGGREGATE_CHAIN_FORK_DECISIONS_VERSION = 1
AGGREGATE_CHAIN_FORK_DECISION_AGGREGATE_VERSION = 1

_ACFD_PACKET = _CFD_DECISION
_ACFD_INPUTS = PFDA_INPUTS
_ACFD_DECLARATION = PFDA_DECLARATION
_ACFD_PRUNE_POLICY_DIGEST = PFDA_PRUNE_POLICY_DIGEST
_ACFD_AUTHORIZATION_POLICY_DIGEST = _ACF_AUTHORIZATION_POLICY_DIGEST
_ACFD_SITE_POLICY_DIGEST = PAFD_SITE_POLICY_DIGEST
_ACFD_DECISION_SITE_POLICY_DIGEST = PFDA_DECISION_SITE_POLICY_DIGEST
_ACFD_AGGREGATE_DIGEST = PFDA_AGGREGATE_DIGEST

_ACFD_PAYLOAD_KEYS = frozenset((
    _ACFD_INPUTS,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    _ACFD_PRUNE_POLICY_DIGEST,
    _ACFD_AUTHORIZATION_POLICY_DIGEST,
    _ACFD_SITE_POLICY_DIGEST,
    _ACFD_DECISION_SITE_POLICY_DIGEST,
    _ACFD_DECLARATION,
    STATUS,
    VERSION,
))
_ACFD_RESULT_KEYS = (
    _ACFD_AGGREGATE_DIGEST,
    _ACFD_INPUTS,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    _ACFD_PRUNE_POLICY_DIGEST,
    _ACFD_AUTHORIZATION_POLICY_DIGEST,
    _ACFD_SITE_POLICY_DIGEST,
    _ACFD_DECISION_SITE_POLICY_DIGEST,
    _ACFD_DECLARATION,
    STATUS,
    VERSION,
)

def verify_aggregate_decision_chains(
    items, prune_policy, authorization_policy, site_policy, keyring, moment,
):
    """Verify a batch of aggregate decision chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy, ``authorization_policy`` the invariant
    site authorization policy and ``site_policy`` the invariant
    fork-proof signer site policy shared by every chain, and ``keyring``
    and ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only batch-level faults raise (container, element or field type
    faults :class:`TypeError`, a :class:`bool` never posing as an int;
    an empty list, an empty or duplicate id, a wrong key set, a wrong
    policy count or an illegal moment :class:`ValueError`).

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_aggregate_decision_chain` rules:
    one chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are grouped by their ``rootDigest`` and only
    successor trajectories under the same root are compared: the same
    predecessor digest pointing at two distinct successor digests is a
    fork, while a plain prefix extension (one chain growing longer along
    the same packets) is not.  Every verified chain crossing a forking
    edge is reclassified ``conflicted`` with its verified result kept
    and its ``error`` fixed to
    ``"forked-aggregate-decision-chain"``; invalid and unauthenticated
    chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted stably by
    ``rootDigest`` then ``predecessorDigest``; each entry carries
    exactly ``rootDigest``, ``predecessorDigest``, ``successors`` (the
    forking successor digests, ascending) and ``ids`` (the ascending
    ids of the chains crossing the edge).  Each item report preserves
    the input order and carries, in this key order, ``error``, ``id``,
    ``result`` and ``status``.  No file is read or written and no input
    is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_adc_chain_item(
            item, prune_policy, authorization_policy, site_policy, keyring,
            verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _ADC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: AGGREGATE_DECISION_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

def _adc_parse_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adc_anchor_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adc_anchor_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adc_anchor_keys
        )
    except json.JSONDecodeError as exc:
        raise _adc_anchor_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _ADC_ANCHOR_TOP_KEYS:
        raise _adc_anchor_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _adc_anchor_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _ADC_ANCHOR_PAYLOAD_KEYS:
        raise _adc_anchor_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (_ADC_ROOT_DIGEST, FAC_HEAD_DIGEST, _ADC_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _adc_anchor_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_ADC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _adc_anchor_invalid("payload height must be non-negative")
    policy_version = payload[_ADC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _adc_anchor_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _adc_anchor_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adc_anchor_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adc_anchor_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != AGGREGATE_DECISION_CHAIN_VERSION:
        raise _adc_anchor_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _adc_anchor_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_aggregate_decision_head(
    items, target, prune_policy, authorization_policy, site_policy, keyring,
    moment, issuer, version,
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_aggregate_decision_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though a fork it shares still reclassifies it.  The
    anchor binds that chain's root digest, head digest and height
    together with the head decision policy digest, the head policy
    version and the sealing moment, and is signed with HMAC-SHA256 under
    the exact ``issuer``/``version`` key usable at ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateChainForkDecisionAggregateError` or
    :class:`InvalidAggregateDecisionChainError`; a signing credential
    fault raises :class:`AuthenticationError`.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        seal_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        _ADC_ROOT_DIGEST: result[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: result[_ADC_HEIGHT],
        _ADC_POLICY_DIGEST: _pac_policy_digest(head_policy),
        _ADC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: AGGREGATE_DECISION_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_aggregate_decision_head(
    anchor, items, target, prune_policy, authorization_policy, site_policy,
    keyring, moment,
):
    """Re-verify a sealed aggregate decision anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against the
    current keyring key bound to its exact issuer and version, usable at
    the verification ``moment``; its sealing moment must not be later
    than the verification moment.  The original batch (with ``target``
    naming the anchored chain) is then re-run through
    :func:`verify_aggregate_decision_chains`; the target must again
    verify with no fork and an accepted head, and its root digest, head
    digest, height, policy digest, policy version and sealing moment
    must still match.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a malformed root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError`; a bad
    anchor, successor or chain binding raises
    :class:`InvalidAggregateDecisionAnchorError` or
    :class:`InvalidAggregateDecisionChainError`; a signature or
    credential fault raises :class:`AuthenticationError`.  No file is
    read or written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _adc_parse_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision anchor signature does not match"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _adc_anchor_invalid(
            "the anchor sealing moment is later than the verification moment"
        )

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        verify_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise _adc_anchor_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _adc_anchor_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[_ADC_ROOT_DIGEST] != payload[_ADC_ROOT_DIGEST]:
        raise _adc_anchor_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _adc_anchor_invalid("head digest does not match the anchor")
    if result[_ADC_HEIGHT] != payload[_ADC_HEIGHT]:
        raise _adc_anchor_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[_ADC_POLICY_VERSION]:
        raise _adc_anchor_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[_ADC_POLICY_DIGEST]:
        raise _adc_anchor_invalid("policy digest does not match the anchor")
    return {
        _ADC_ROOT_DIGEST: payload[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: payload[_ADC_HEIGHT],
        _ADC_POLICY_DIGEST: head_policy_digest,
        _ADC_POLICY_VERSION: payload[_ADC_POLICY_VERSION],
        _ADC_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }

def _reject_duplicate_pac_fork_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _pac_fork_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_chain_materials(validated_items: list[dict]) -> list[dict]:
    """Digest summary of every input chain, strictly in input order."""
    return [
        {
            ID: item[ID],
            PAC_BATCH_ROOT: hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest(),
            PAC_BATCH_SUCCESSORS: [
                hashlib.sha256(successor).hexdigest()
                for successor in item[PAC_BATCH_SUCCESSORS]
            ],
            PAC_BATCH_POLICIES: [
                _pac_policy_digest(validated_policy)
                for validated_policy in _pac_validated_policy_sequence(
                    item[PAC_BATCH_POLICIES]
                )
            ],
        }
        for item in validated_items
    ]


def _validated_pac_fork_chains(chains: object, invalid=_pac_fork_proof_invalid):
    """Validate the bound chain material summary into fresh ordered dicts.

    Each entry must carry exactly ``id`` (a non-empty str, unique across
    the summary), ``root`` (the chain root's digest), ``successors``
    (the ordered successor digests, possibly empty) and ``policies``
    (the per-stage policy digests, exactly one more than the
    successors).  A field of the wrong type raises :class:`TypeError`;
    every key-set, value-format or count fault is raised through
    ``invalid`` (the prune aggregate fork proof error by default).
    """
    if not isinstance(chains, list):
        raise TypeError("payload chains must be a list")
    if not chains:
        raise invalid("payload chains must be non-empty")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, chain in enumerate(chains):
        where = f"chain {position}"
        if not isinstance(chain, dict):
            raise TypeError(f"{where} must be an object")
        if set(chain.keys()) != _PAC_FORK_CHAIN_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        chain_id = chain[ID]
        if not isinstance(chain_id, str):
            raise TypeError(f"{where} id must be a str")
        if chain_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if chain_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(chain_id)
        root = chain[PAC_BATCH_ROOT]
        if not isinstance(root, str):
            raise TypeError(f"{where} root must be a str")
        if not _prune_is_digest(root):
            raise invalid(
                f"{where} root must be 64 lowercase hex characters"
            )
        successors = chain[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, str):
                raise TypeError(f"{where} successor {hop_index} must be a str")
            if not _prune_is_digest(successor):
                raise invalid(
                    f"{where} successor {hop_index} must be 64 lowercase hex "
                    "characters"
                )
        policies = chain[PAC_BATCH_POLICIES]
        if not isinstance(policies, list):
            raise TypeError(f"{where} policies must be a list")
        if not policies:
            raise invalid(
                f"{where} policies must be non-empty"
            )
        for policy_index, policy_digest in enumerate(policies):
            if not isinstance(policy_digest, str):
                raise TypeError(
                    f"{where} policy {policy_index} must be a str"
                )
            if not _prune_is_digest(policy_digest):
                raise invalid(
                    f"{where} policy {policy_index} must be 64 lowercase hex "
                    "characters"
                )
        if len(policies) != len(successors) + 1:
            raise invalid(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        validated.append({
            ID: chain_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _validated_pac_fork_chain_result(
    result: object, chain: dict, where: str,
    invalid=_pac_fork_proof_invalid,
) -> None:
    """Validate one verified chain summary against its chain material.

    The summary must follow the exact single-chain verification result
    shape of the fork batch the proof was issued over and every digest
    and the height must match the bound chain material.  A field of the
    wrong type raises :class:`TypeError` (a :class:`bool` never poses as
    an int); every key-set, value-format or binding fault is raised
    through ``invalid`` (the prune aggregate fork proof error by
    default).
    """
    if set(result.keys()) != _PAC_CHAIN_RESULT_KEYS:
        raise invalid(
            f"{where} result must contain exactly the keys 'commonDigest', "
            "'headDigest', 'height', 'policyVersion', 'rootDigest' and "
            "'status'"
        )
    root_digest = result[PAC_ROOT_DIGEST]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} result rootDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} result rootDigest must be 64 lowercase hex characters"
        )
    if root_digest != chain[PAC_BATCH_ROOT]:
        raise invalid(
            f"{where} result rootDigest does not match the chain material"
        )
    head_digest = result[PAC_HEAD_DIGEST]
    if not isinstance(head_digest, str):
        raise TypeError(f"{where} result headDigest must be a str")
    if not _prune_is_digest(head_digest):
        raise invalid(
            f"{where} result headDigest must be 64 lowercase hex characters"
        )
    successors = chain[PAC_BATCH_SUCCESSORS]
    expected_head = successors[-1] if successors else chain[PAC_BATCH_ROOT]
    if head_digest != expected_head:
        raise invalid(
            f"{where} result headDigest does not match the chain material"
        )
    height = result[PAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError(f"{where} result height must be an int")
    if height != len(successors):
        raise invalid(
            f"{where} result height does not match the chain material"
        )
    policy_version = result[PAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError(f"{where} result policyVersion must be an int")
    if policy_version <= 0:
        raise invalid(
            f"{where} result policyVersion must be positive"
        )
    status = result[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} result status must be a str")
    if status not in _PAC_CHAIN_RESULT_STATUSES:
        raise invalid(
            f"{where} result status is not a known stage status"
        )
    common_digest = result[PAC_COMMON_DIGEST]
    if common_digest is not None:
        if not isinstance(common_digest, str):
            raise TypeError(f"{where} result commonDigest must be a str")
        if not _prune_is_digest(common_digest):
            raise invalid(
                f"{where} result commonDigest must be 64 lowercase hex "
                "characters"
            )


def _validated_pac_fork_report(
    report: object, chains: list[dict], *,
    conflicted_error=_PAC_CHAIN_ITEM_ERROR,
    invalid=_pac_fork_proof_invalid,
    report_version=PRUNE_AGGREGATE_CHAINS_VERSION,
) -> None:
    """Validate the complete chain-batch report bound into a fork proof.

    The report must follow the exact fork-chain batch report shape --
    ``forks``, ``items`` and ``version`` (the integer 1) -- with at
    least one fork.  Every binding to the chain material summary is
    checked: the item count and per-position ids, each verified
    result's digests and height, and each fork's exact forking
    successors and crossing chains recomputed from the bound materials.
    ``conflicted_error`` names the fixed error a conflicted item must
    carry.  A field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every key-set, value,
    ordering, reference or binding fault is raised through ``invalid``.
    """
    if not isinstance(report, dict):
        raise TypeError("payload report must be an object")
    if set(report.keys()) != _PAC_FORK_REPORT_KEYS:
        raise invalid(
            "bound report must contain exactly the keys 'forks', 'items' "
            "and 'version'"
        )
    version = report[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("bound report version must be an int")
    if version != report_version:
        raise invalid(
            "bound report version must be the integer 1"
        )

    items = report[ITEMS]
    if not isinstance(items, list):
        raise TypeError("bound report items must be a list")
    if not items:
        raise invalid("bound report items must be non-empty")
    if len(items) != len(chains):
        raise invalid(
            "bound report item count does not match the chain materials"
        )

    seen_ids: set[str] = set()
    for position, item_report in enumerate(items):
        where = f"bound report item {position}"
        if not isinstance(item_report, dict):
            raise TypeError(f"{where} must be an object")
        if set(item_report.keys()) != _PAC_FORK_ITEM_REPORT_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'error', 'id', "
                "'result' and 'status'"
            )
        item_id = item_report[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if item_id != chains[position][ID]:
            raise invalid(
                f"{where} id does not match the chain material at its position"
            )
        if item_id in seen_ids:
            raise invalid(f"{where} repeats an id")

        seen_ids.add(item_id)
        status = item_report[STATUS]
        if not isinstance(status, str):
            raise TypeError(f"{where} status must be a str")
        if status not in _PAC_FORK_REPORT_STATUSES:
            raise invalid(
                f"{where} status is not a known status"
            )
        error = item_report[CHECKPOINT_ITEM_ERROR]
        result = item_report[VERDICT_ITEM_RESULT]
        if status == PAC_CHAINS_VERIFIED:
            if error is not None:
                raise invalid(
                    f"{where} error must be null when verified"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when verified"
                )
        elif status == PAC_CHAINS_CONFLICTED:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str when conflicted")
            if error != conflicted_error:
                raise invalid(
                    f"{where} error must be {conflicted_error!r} when "
                    "conflicted"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when conflicted"
                )
        else:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str for a failure")
            if error == "":
                raise invalid(
                    f"{where} error must be a non-empty str for a failure"
                )
            if result is not None:
                raise invalid(
                    f"{where} result must be null for a failure"
                )
        if isinstance(result, dict):
            _validated_pac_fork_chain_result(
                result, chains[position], where, invalid=invalid
            )

    forks = report[CHAINS_FORKS]
    if not isinstance(forks, list):
        raise TypeError("bound report forks must be a list")
    if not forks:
        raise invalid(
            "a fork proof must report at least one fork"
        )

    # Recompute every edge from the bound materials over the items that
    # verified, then demand the bound fork entries match exactly -- the
    # same grouping and fork rule the fork-chain batch uses.
    groups: dict[str, dict[str, set[str]]] = {}
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    expected_edges: dict[tuple[str, str], set[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                expected_edges[(root_digest, upstream)] = digests
    crossing: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in expected_edges
    }
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        for upstream in nodes[:-1]:
            edge = (nodes[0], upstream)
            if edge in expected_edges:
                crossing[edge].add(chain[ID])

    seen_edges: set[tuple[str, str]] = set()
    previous_edge: tuple[str, str] | None = None
    for position, fork in enumerate(forks):
        where = f"bound report fork {position}"
        if not isinstance(fork, dict):
            raise TypeError(f"{where} must be an object")
        if set(fork.keys()) != _PAC_CHAIN_FORK_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'ids', "
                "'predecessorDigest', 'rootDigest' and 'successors'"
            )
        root_digest = fork[PAC_ROOT_DIGEST]
        predecessor = fork[PAC_PREDECESSOR_DIGEST]
        if not isinstance(root_digest, str):
            raise TypeError(f"{where} rootDigest must be a str")
        if not isinstance(predecessor, str):
            raise TypeError(f"{where} predecessorDigest must be a str")
        if not _prune_is_digest(root_digest):
            raise invalid(
                f"{where} rootDigest must be 64 lowercase hex characters"
            )
        if not _prune_is_digest(predecessor):
            raise invalid(
                f"{where} predecessorDigest must be 64 lowercase hex "
                "characters"
            )
        edge = (root_digest, predecessor)
        if edge in seen_edges:
            raise invalid(f"{where} repeats a fork edge")
        seen_edges.add(edge)
        if previous_edge is not None and edge < previous_edge:
            raise invalid(
                f"{where} forks must be sorted by rootDigest then "
                "predecessorDigest"
            )
        previous_edge = edge
        if edge not in expected_edges:
            raise invalid(
                f"{where} is not a fork in the bound chain materials"
            )
        successors = fork[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        if any(not isinstance(successor, str) for successor in successors):
            raise TypeError(f"{where} successors must be strs")
        if any(not _prune_is_digest(successor) for successor in successors):
            raise invalid(
                f"{where} successors must be 64 lowercase hex characters"
            )
        if successors != sorted(successors) or len(set(successors)) != len(
            successors
        ):
            raise invalid(
                f"{where} successors must be unique and sorted ascending"
            )
        if set(successors) != expected_edges[edge]:
            raise invalid(
                f"{where} successors do not match the forking edge"
            )
        ids = fork[_FORK_IDS]
        if not isinstance(ids, list):
            raise TypeError(f"{where} ids must be a list")
        if any(not isinstance(fork_id, str) for fork_id in ids):
            raise TypeError(f"{where} ids must be strs")
        if any(fork_id == "" for fork_id in ids):
            raise invalid(f"{where} ids must be non-empty")
        if ids != sorted(ids) or len(set(ids)) != len(ids):
            raise invalid(
                f"{where} ids must be unique and sorted ascending"
            )
        if set(ids) != crossing[edge]:
            raise invalid(
                f"{where} ids do not match the chains crossing the edge"
            )

    if seen_edges != set(expected_edges):
        raise invalid(
            "the bound forks do not match the forking edges in the materials"
        )
    conflicted = {
        item_report[ID]
        for item_report in items
        if item_report[STATUS] == PAC_CHAINS_CONFLICTED
    }
    all_fork_ids: set[str] = set()
    for edge_crossing in crossing.values():
        all_fork_ids |= edge_crossing
    if conflicted != all_fork_ids:
        raise invalid(
            "the fork id sets must equal the conflicted report items"
        )


def _parse_pac_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate fork proof bytes into ``(payload, signature, chains)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, count, ordering, reference or
    report-binding fault raises
    :class:`InvalidAggregateForkProofError`.  The policy, moment,
    credential and signature bindings are checked by
    :func:`verify_prune_aggregate_fork_proof`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pac_fork_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pac_fork_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _PAC_FORK_PROOF_TOP_KEYS:
        raise _pac_fork_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _pac_fork_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _PAC_FORK_PROOF_PAYLOAD_KEYS:
        raise _pac_fork_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'policy', 'report' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pac_fork_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pac_fork_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _pac_fork_proof_invalid("payload moment must be non-negative")
    policy_digest = payload[RECEIPT_POLICY]
    if not isinstance(policy_digest, str):
        raise TypeError("payload policy must be a str")
    if not _prune_is_digest(policy_digest):
        raise _pac_fork_proof_invalid(
            "payload policy must be 64 lowercase hex characters"
        )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != PRUNE_AGGREGATE_FORK_PROOF_VERSION:
        raise _pac_fork_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(payload[FORK_PROOF_CHAINS])
    _validated_pac_fork_report(payload[FORK_PROOF_REPORT], chains)

    if _prune_compact(data) != raw:
        raise _pac_fork_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_prune_aggregate_fork_proof(
    items, prune_policy, keyring, moment, issuer, version
):
    """Sign the fork summary of a prune aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_prune_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original pruning policy, ``keyring`` follows
    the existing rules, ``moment`` is the signing time and
    ``issuer``/``version`` name the signing credentials.  The batch
    first runs through the exact :func:`verify_prune_aggregate_chains`
    rules and the proof is issued only when the resulting report
    records at least one fork.  No file is read or written and no
    argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every
    object key recursively sorted, non-ASCII preserved, no trailing
    newline or any other trailing byte -- carrying exactly ``payload``
    and ``signature``.  The payload binds exactly ``chains``,
    ``issuer``, ``keyVersion``, ``moment``, ``policy`` (the lowercase
    hex SHA-256 of the canonical compact prune policy encoding),
    ``report`` (the complete chain-batch report) and ``version`` (the
    integer 1).  ``chains`` summarizes every input chain, strictly in
    input order with no reordering, omission or replacement: each entry
    carries exactly ``id``, ``root`` (the SHA-256 of the chain's root
    bytes), ``successors`` (the SHA-256 of each successor's complete
    bytes in chain order) and ``policies`` (the SHA-256 of each stage
    policy's canonical bytes in history order).  ``signature`` is the
    lowercase hex HMAC-SHA256 of the canonical compact payload bytes
    under the key the keyring binds to the exact issuer and version,
    with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy value or a
    report without a fork raises :class:`ValueError`; and unknown,
    revoked, not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_prune_aggregate_chains(
        validated_items, prune_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a prune aggregate fork proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        RECEIPT_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_pac_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork proof against already-validated shared materials.

    This is the shared core of :func:`verify_prune_aggregate_fork_proof`
    and the batch :func:`verify_prune_aggregate_fork_proofs`; the caller
    owns the argument-type and shared-material validation.  The returned
    dict is freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_pac_fork_proof(raw)
    recomputed_policy = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[RECEIPT_POLICY] != recomputed_policy:
        raise _pac_fork_proof_invalid(
            "policy digest does not match the policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _pac_fork_proof_invalid(
            "moment must not be later than the verification moment"
        )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune aggregate fork proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        VD_POLICY_DIGEST: recomputed_policy,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }


def verify_prune_aggregate_fork_proof(proof, prune_policy, keyring, moment):
    """Re-verify a signed prune aggregate fork proof entirely offline.

    Only the proof bytes, the expected shared ``prune_policy``, the
    current ``keyring`` and the verification ``moment`` are consulted
    -- no file is read or written and no argument is modified.
    Verification validates the proof encoding, key sets, version,
    digests, counts, ordering and chain/report references, recomputes
    the forking edges, the crossing chain ids and the conflicted set
    purely from the bound chain materials and demands the bound report
    match exactly, recomputes the prune policy digest, requires the
    signing moment not to be later than the verification moment, and
    verifies the HMAC-SHA256 signature against the key the *current*
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the proof.

    On success a fresh independent mapping is returned with the fixed
    keys ``chains``, ``issuer``, ``keyVersion``, ``moment``,
    ``policyDigest``, ``proofDigest`` (the lowercase hex SHA-256 of the
    proof bytes), ``report`` and ``version`` (the integer 1).  A
    non-bytes proof or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    illegal policy, keyring or moment raises :class:`ValueError`; an
    illegal encoding, key set, version, digest, count, ordering,
    reference or report binding raises
    :class:`InvalidAggregateForkProofError` (a :class:`ValueError`
    subclass); and unknown, revoked, not-yet-valid or expired
    credentials or a signature mismatch raise
    :class:`AuthenticationError`.
    """
    if not isinstance(proof, bytes):
        raise TypeError("proof must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    return _verify_pac_fork_proof_core(
        proof, validated_prune_policy, validated_keyring, verify_moment
    )


# -- Offline batch verification of prune aggregate fork proofs ----------------

PAC_FORK_PROOFS_VERSION = 1

_PAC_FORK_PROOF_BATCH_ITEM_KEYS = frozenset((ID, FORK_PROOF_ITEM_PROOF))
_PAC_FORK_PROOFS_VERIFIED = "verified"
_PAC_FORK_PROOFS_INVALID = "invalid-proof"
_PAC_FORK_PROOFS_UNAUTHENTICATED = "unauthenticated"


def _validated_pac_fork_proof_items(items: object) -> list[dict]:
    """Validate the fork-proof batch before any proof is verified.

    The argument must be a non-empty list of dicts each holding exactly
    ``id`` (a non-empty str, unique across the batch) and ``proof``
    (bytes).  Container, element and field type faults raise
    :class:`TypeError`; an empty list, an empty or duplicate id or a
    wrong key set raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if set(item.keys()) != _PAC_FORK_PROOF_BATCH_ITEM_KEYS:
            raise ValueError(
                f"{where} must contain exactly the keys 'id' and 'proof'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise ValueError(f"{where} id must be non-empty")
        if item_id in seen_ids:
            raise ValueError(f"duplicate id {item_id!r}")
        seen_ids.add(item_id)
        proof = item[FORK_PROOF_ITEM_PROOF]
        if not isinstance(proof, bytes):
            raise TypeError(f"{where} proof must be bytes")
        validated.append({ID: item_id, FORK_PROOF_ITEM_PROOF: proof})
    return validated


def _pac_fork_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One fork-proof batch report with the fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_pac_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one prune aggregate fork proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    proof = item[FORK_PROOF_ITEM_PROOF]
    try:
        result = _verify_pac_fork_proof_core(
            proof, validated_prune_policy, validated_keyring, moment
        )
    except AuthenticationError as exc:
        return _pac_fork_proofs_item_report(
            item_id, _PAC_FORK_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateForkProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _pac_fork_proofs_item_report(
            item_id, _PAC_FORK_PROOFS_INVALID, str(exc), None
        )
    return _pac_fork_proofs_item_report(
        item_id, _PAC_FORK_PROOFS_VERIFIED, None, result
    )


def verify_prune_aggregate_fork_proofs(
    items: list, prune_policy: dict, keyring: dict, moment: int
) -> dict:
    """Verify a whole batch of prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
